/**
 * TPK Contents Parser — parses `tpk_contents` JSON files for native app RDS.
 *
 * The `tpk_contents` file is generated by tizen-core during the build process
 * and contains a JSON array of source -> destination path mappings.
 *
 * Format: `["relToDebug || .tpk/path", ...]`
 * Example: `["tpk/bin/myapp || .tpk/bin/myapp", "../shared/res/icon.png || .tpk/shared/res/icon.png"]`
 *
 * Each entry is split by ` || `:
 *   - Left side: source path relative to the build output directory (e.g. `Debug/`)
 *   - Right side: destination path in the `.tpk/` staging directory
 *
 * For RDS, the source paths (left side) are resolved relative to the project
 * root directory, since those are the actual files on the host to track and
 * hash.
 *
 * Reference: tizen-core/pkg/ws/pack_cmd.go:284-389
 * Ported from packages/server/src/features/rds/tpk-contents-parser.ts.
 *
 * @module core/rds/tpk-contents-parser
 */

const fs = require("fs");
const path = require("path");

const ENTRY_SEPARATOR = " || ";
const TPK_PREFIX = ".tpk/";

/**
 * @typedef {object} TpkContentEntry
 * @property {string} sourcePath - relative to the project root (e.g. `Debug/tpk/bin/myapp`)
 * @property {string} destPath - relative to the app install dir on device
 *   (e.g. `bin/myapp`) — `.tpk/` prefix stripped
 */

/**
 * @typedef {object} TpkContentsResult
 * @property {TpkContentEntry[]} entries - all parsed entries
 * @property {string[]} localPaths - sourcePath of every entry, in order — the
 *   actual host files to track for RDS (hash, compare, push)
 * @property {string[]} errors - any entries/content that could not be parsed
 */

/**
 * Parse a `tpk_contents` JSON string into structured entries.
 *
 * Pure — no I/O. Shared core used by parseTpkContents().
 *
 * @param {string} content - raw file content (JSON string)
 * @param {string} [buildDirName="Debug"] - name of the build output directory
 * @returns {TpkContentsResult}
 */
function parseTpkContentsContent(content, buildDirName = "Debug") {
  const entries = [];
  const localPaths = [];
  const errors = [];

  let rawEntries;
  try {
    rawEntries = JSON.parse(content);
  } catch {
    return {
      entries,
      localPaths,
      errors: ["failed to parse tpk_contents JSON"],
    };
  }

  if (!Array.isArray(rawEntries)) {
    return {
      entries,
      localPaths,
      errors: ["tpk_contents is not a JSON array"],
    };
  }

  for (const entry of rawEntries) {
    if (typeof entry !== "string") {
      errors.push(`non-string entry: ${String(entry)}`);
      continue;
    }

    const separatorIdx = entry.indexOf(ENTRY_SEPARATOR);
    if (separatorIdx === -1) {
      errors.push(`no separator in: "${entry}"`);
      continue;
    }

    const rawSourcePath = entry.substring(0, separatorIdx).trim();
    const rawDestPath = entry
      .substring(separatorIdx + ENTRY_SEPARATOR.length)
      .trim();

    // rawSourcePath is relative to buildDir (e.g. "tpk/bin/myapp" relative to
    // Debug/), so relative to project root it becomes "Debug/tpk/bin/myapp".
    // path.join also normalizes "../" segments, e.g. buildDirName="Debug" +
    // rawSourcePath="../shared/res/icon.png" -> "shared/res/icon.png".
    const sourcePath = path
      .join(buildDirName, rawSourcePath)
      .split(path.sep)
      .join("/");

    // Strip ".tpk/" prefix from dest path for the device-relative path:
    // ".tpk/bin/myapp" -> "bin/myapp"
    const destPath = rawDestPath.startsWith(TPK_PREFIX)
      ? rawDestPath.substring(TPK_PREFIX.length)
      : rawDestPath;

    entries.push({ sourcePath, destPath });
    localPaths.push(sourcePath);
  }

  return { entries, localPaths, errors };
}

/**
 * Parse a `tpk_contents` file.
 *
 * A missing file is not an error — it means the project hasn't been built
 * yet (or isn't a native project), so an empty result with no errors is
 * returned. A file that exists but can't be read or parsed produces a
 * populated `errors` array instead of throwing.
 *
 * @param {string} tpkContentsPath - absolute path to the `tpk_contents` file
 * @param {string} [buildDirName="Debug"] - name of the build output directory
 * @returns {TpkContentsResult}
 */
function parseTpkContents(tpkContentsPath, buildDirName = "Debug") {
  if (!fs.existsSync(tpkContentsPath)) {
    return { entries: [], localPaths: [], errors: [] };
  }

  let content;
  try {
    content = fs.readFileSync(tpkContentsPath, "utf-8");
  } catch {
    return {
      entries: [],
      localPaths: [],
      errors: ["failed to read tpk_contents"],
    };
  }

  return parseTpkContentsContent(content, buildDirName);
}

/**
 * Async version of {@link parseTpkContents}.
 *
 * Uses `fs.promises.readFile` so the event loop is not blocked during I/O.
 * Produces the same result as the sync version for the same file.
 *
 * @param {string} tpkContentsPath - absolute path to the `tpk_contents` file
 * @param {string} [buildDirName="Debug"] - name of the build output directory
 * @returns {Promise<TpkContentsResult>}
 */
async function parseTpkContentsAsync(tpkContentsPath, buildDirName = "Debug") {
  if (!fs.existsSync(tpkContentsPath)) {
    return { entries: [], localPaths: [], errors: [] };
  }

  let content;
  try {
    content = await fs.promises.readFile(tpkContentsPath, "utf-8");
  } catch {
    return {
      entries: [],
      localPaths: [],
      errors: ["failed to read tpk_contents"],
    };
  }

  return parseTpkContentsContent(content, buildDirName);
}

/**
 * Find the `tpk_contents` file for a native project.
 *
 * @param {string} buildDir - absolute path to the build output directory
 *   (e.g. `<project>/Debug`)
 * @returns {string|null} absolute path to the `tpk_contents` file, or null
 *   if not found
 */
function findTpkContentsPath(buildDir) {
  const fullPath = path.join(buildDir, "tpk_contents");
  return fs.existsSync(fullPath) ? fullPath : null;
}

module.exports = {
  parseTpkContentsContent,
  parseTpkContents,
  parseTpkContentsAsync,
  findTpkContentsPath,
};
